import sys

def first_missing_positive_brute(nums):
    n = len(nums)
    for i in range(1, n + 2):
        found = False
        for x in nums:
            if x == i:
                found = True
                break
        if not found:
            return i
    return n + 1

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(first_missing_positive_brute(nums))

import sys

def first_missing_positive_best(nums):
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            j = nums[i] - 1
            nums[i], nums[j] = nums[j], nums[i]
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1
    return n + 1

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(first_missing_positive_best(nums))
